import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        double x = sc.nextDouble();
        double y = sc.nextDouble();
        int n = sc.nextInt();

        int num = 0, den = 1;
        double ratio = x / y;
        double min_diff = 1e9;

        for (int i = 1; i <= n; i++) {
            int low = (int) Math.floor(ratio * i);
            int high = (int) Math.ceil(ratio * i);

            if (Math.abs(ratio - (double) low / i) + 1e-15 < min_diff) {
                num = low;
                den = i;
                min_diff = Math.abs(ratio - (double) low / i);
            }
            if (Math.abs(ratio - (double) high / i) + 1e-15 < min_diff) {
                num = high;
                den = i;
                min_diff = Math.abs(ratio - (double) high / i);
            }
        }

        int g = gcd(num, den);
        System.out.println((num / g) + "/" + (den / g));
    }

    private static int gcd(int a, int b) {
        while (b != 0) {
            int temp = b;
            b = a % b;
            a = temp;
        }
        return a;
    }
}
